function serviceCopy(zh,en){return state.lang==='en'?en:zh}
function serviceCityName(city){return state.lang==='en'?city.nameEn:city.name}
function uiIcon(name){return `<span class="ui-icon" style="--icon:url('./vendor/feather/${name}.svg')" aria-hidden="true"></span>`}
function serviceEmailURL(city){const subject=serviceCopy('YICHEN Drive · '+(city?city.name:'')+'租车咨询','YICHEN Drive · '+(city?city.nameEn+' ':'')+'rental enquiry');return 'mailto:'+YICHEN_CONTACT.email+'?subject='+encodeURIComponent(subject)}
function serviceMapURL(city){return 'https://uri.amap.com/search?keyword='+encodeURIComponent(city.name)+'&city='+encodeURIComponent(city.name)+'&view=map&callnative=0'}
function serviceAddressURL(){return 'https://uri.amap.com/search?keyword='+encodeURIComponent(YICHEN_CONTACT.address)+'&city='+encodeURIComponent('成都')+'&view=map&callnative=0'}
function serviceCityLink(city){return '#/services?city='+city.id}
function serviceFooter(){return `<footer class="service-footer"><div class="wrap"><div class="footer-grid"><div class="footer-intro"><a href="#/" class="brand brand-lockup" aria-label="YICHEN Drive 首页"><span class="brand-mark" aria-hidden="true"><img src="./images/brand/yichen-logo.svg?v=logo-v8" width="48" height="48" alt=""/></span><span class="brand-wordmark"><strong>YICHEN</strong><span>DRIVE</span></span></a><p>${serviceCopy('立足成都，连接四川 12 座服务城市。为城市出行与山水旅程，找到更合适的座驾。','Based in Chengdu, serving 12 cities across Sichuan. Find the right vehicle for city journeys and scenic escapes.')}</p></div><div class="footer-cities"><h4>${serviceCopy('服务城市','Service cities')}</h4><div class="footer-city-grid">${SERVICE_CITIES.map(city=>`<a href="${serviceCityLink(city)}">${serviceCityName(city)}</a>`).join('')}</div></div><div class="footer-quick"><h4>${serviceCopy('快速链接','Quick links')}</h4><a href="#/search">${serviceCopy('车型库','Vehicle collection')}</a><a href="#/services?section=process">${serviceCopy('租车流程','How to rent')}</a><a href="#/services">${serviceCopy('服务地区','Service areas')}</a><a href="#/match">${serviceCopy('选车推荐','Find your match')}</a><a href="#/search">${serviceCopy('立即选车','Choose a vehicle')}</a></div><div class="footer-contact" id="contact-us"><h4>${serviceCopy('联系我们','Contact us')}</h4><div class="contact-placeholder">${uiIcon('phone')}<span>${serviceCopy('电话联系','Telephone')}</span><span class="contact-blank" aria-label="${serviceCopy('暂未填写','Not supplied')}"></span></div><div class="contact-placeholder">${uiIcon('message-circle')}<span>${serviceCopy('微信联系','WeChat')}</span><span class="contact-blank" aria-label="${serviceCopy('暂未填写','Not supplied')}"></span></div>${YICHEN_CONTACT.phone?`<a href="tel:${esc(YICHEN_CONTACT.phone)}">${uiIcon('phone')}${esc(YICHEN_CONTACT.phone)}</a>`:''}<a href="mailto:${YICHEN_CONTACT.email}">${uiIcon('mail')}<span>${YICHEN_CONTACT.email}</span></a><a href="${serviceAddressURL()}" target="_blank" rel="noopener noreferrer">${uiIcon('map-pin')}<span>${serviceCopy(YICHEN_CONTACT.address,YICHEN_CONTACT.addressEn)}</span></a><a class="footer-contact-cta" href="${serviceEmailURL()}">${serviceCopy('邮件咨询用车','Enquire by email')}${uiIcon('arrow-up-right')}</a></div></div><div class="footer-bottom"><span>© 2026 YICHEN Drive.</span><span>${serviceCopy('车辆价格与订单为演示数据','Vehicle prices and orders are demo data')} · <a href="./photo-credits.html" target="_blank" rel="noopener noreferrer">${serviceCopy('摄影来源与许可','Photography credits')}</a> · <a href="./service-map-sources.html" target="_blank" rel="noopener noreferrer">${serviceCopy('地图来源','Map credits')}</a></span></div></div></footer>`}
function servicePage(){const params=new URLSearchParams(state.route.split('?')[1]||''),picked=params.get('city');if(SERVICE_CITIES.some(c=>c.id===picked))state.serviceCity=picked;const active=SERVICE_CITIES.find(c=>c.id===state.serviceCity)||SERVICE_CITIES[0],lang=state.lang==='en'?'en':'zh';return `<main class="page wrap service-page"><div class="subhero"><span class="eyebrow">SERVICE AREAS · SICHUAN</span><h1>${serviceCopy('从成都出发，连接四川。','From Chengdu, across Sichuan.')}</h1><p>${serviceCopy('12 座服务城市，为你的下一段旅程做好准备。','Twelve service cities for the next part of your journey.')}</p></div><section class="service-layout" aria-label="${serviceCopy('服务城市地图','Service city map')}"><div class="service-map-card"><div class="service-map-heading"><span>YICHEN · SICHUAN</span><b>${serviceCopy('服务城市地图','Service city map')}</b></div><img id="service-map-image" src="./images/service-regions/${active.id}-${lang}.png" width="1100" height="1000" alt="${serviceCopy('四川服务城市地图，当前选中'+active.name,'Sichuan service city map, selected '+active.nameEn)}"/><div class="service-map-legend"><span>${uiIcon('map-pin')}${serviceCopy('已开通服务的城市','Cities with service')}</span><small>${serviceCopy('城市位置示意，具体取还车点提前确认。','City locations are illustrative. Confirm pickup and return points in advance.')}</small></div></div><div class="service-city-panel"><div class="service-city-heading"><span class="eyebrow">12 CITIES, ONE JOURNEY</span><h2>${serviceCopy('选择服务城市','Choose a service city')}</h2></div><div class="service-city-grid">${SERVICE_CITIES.map(city=>`<button class="service-city-card ${city.id===active.id?'active':''}" onclick="selectServiceCity('${city.id}')" aria-pressed="${city.id===active.id}"><strong>${uiIcon('map-pin')}${serviceCityName(city)}</strong><span>${serviceCopy(city.summary,city.summaryEn)}</span></button>`).join('')}</div><div class="service-selected" aria-live="polite"><span>${serviceCopy('当前城市','Selected city')}</span><h3>${serviceCityName(active)}</h3><p>${serviceCopy('告知取还车地点、日期与车型偏好，我们通过邮件为你确认用车安排。','Share pickup and return points, dates and vehicle preferences. We can confirm arrangements by email.')}</p><div><a class="btn" href="${serviceEmailURL(active)}">${serviceCopy('咨询用车','Enquire about a rental')}${uiIcon('arrow-up-right')}</a><a href="${serviceMapURL(active)}" target="_blank" rel="noopener noreferrer">${serviceCopy('在高德查看城市','View city on AMap')} ↗</a></div></div></div></section>${businessServicesHTML()}${rentalProcessHTML()}</main>`}
function selectServiceCity(id){if(!SERVICE_CITIES.some(c=>c.id===id))return;state.serviceCity=id;const route='/services?city='+id;state.route=route;if(window.history?.replaceState)window.history.replaceState(null,'','#'+route);else location.hash='#'+route;render()}
function finishServicePage(){if(new URLSearchParams(state.route.split('?')[1]||'').get('section')==='process')setTimeout(()=>document.getElementById('rental-process')?.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}),0)}
const CATALOG_REFERENCE_FACTS={
 '718':[['users','双座敞篷','Two-seat roadster'],['briefcase','前后行李厢','Front & rear trunks']],
 x5:[['users','豪华 SUV','Luxury SUV'],['briefcase','家庭与长途','Family & touring']],
 e:[['users','豪华轿车','Executive saloon'],['settings','商务出行','Business journeys']],
 gl8:[['users','7 座车型参考','7-seat model reference'],['settings','9 速自动车型参考','9-speed model reference']],
 'gl8-653':[['users','商务 MPV','Business MPV'],['briefcase','多人同行','Group journeys']],
 coaster:[['users','商务中巴','Business minibus'],['briefcase','团队接送','Group transfers']],
 my:[['zap','纯电动力','Electric power'],['users','五座版车型参考','5-seat model reference']]
};
function catalogSpecs(car){const items=CATALOG_REFERENCE_FACTS[car.id]||[['users',car.type,t(car.type)],['briefcase',car.scene,t(car.scene)]];return items.map(([icon,zh,en])=>`<span class="catalog-spec">${uiIcon(icon)}<span>${serviceCopy(zh,en)}</span></span>`).join('')}

function catalogCard(car,kind='fleet'){const en=state.lang==='en',name=en?car.en:car.name.replace(/（[^）]*）/g,'').trim(),brand=BRANDS.find(b=>b.id===car.brand),priceLabel=car.price==null?serviceCopy('待报价','Quote pending'):money(car.price);return `<article class="${kind==='result'?'result-card':'fleet-card'}"><div class="catalog-media"><a href="#/car/${car.id}" aria-label="${serviceCopy('查看','View')} ${esc(name)}">${vehiclePhoto({...car,image:car.catalogImage||car.image},'loading="lazy" alt="'+esc(name)+'"')}${car.catalogImage?'':vehiclePhotoNotice(car)}</a><span class="catalog-type">${t(car.type)}</span><button class="heart ${state.favorites.includes(car.id)?'active':''}" onclick="favorite('${car.id}')" aria-label="${serviceCopy(state.favorites.includes(car.id)?'取消收藏':'收藏',state.favorites.includes(car.id)?'Remove favourite':'Save favourite')} ${esc(name)}">${uiIcon('heart')}</button></div><div class="catalog-body"><div class="catalog-name-price"><div><h3><a href="#/car/${car.id}">${esc(name)}</a></h3><p>${brand?brand.en:''}</p></div><div class="catalog-price"><strong>${priceLabel}</strong><small>${car.price==null?serviceCopy('请先咨询','Enquire first'):serviceCopy('/ 天 · 演示价','/ day · demo')}</small></div></div><div class="catalog-specs">${catalogSpecs(car)}</div><div class="catalog-actions"><small><a href="./catalog-reference-facts.html">${serviceCopy(car.catalogImage?'AI 整理 · 车型参考':'车型资料参考',car.catalogImage?'AI edited · Model reference':'Model reference')}</a></small><a href="#/car/${car.id}">${serviceCopy('查看车辆','View vehicle')}${uiIcon('arrow-up-right')}</a></div></div></article>`}

function rentalProcessHTML(context='service'){const home=context==='home';return `<section class="rental-process ${home?'wrap home-rental-process':''}" id="${home?'home-rental-process':'rental-process'}"><div class="section-head"><div><span class="eyebrow">A SIMPLE START</span><h2>${serviceCopy('三步，开始你的旅程。','Three steps to your journey.')}</h2></div><a class="btn ghost" href="#/search">${serviceCopy('立即选车','Choose a vehicle')} ↗</a></div><div class="rental-step-grid">${[[uiIcon('map-pin'),'选择地点与日期','Choose places and dates','先确定城市、具体取车地点和出发日期。','Start with the city, pickup point and travel dates.'],[uiIcon('users'),'挑选合适的车型','Choose your vehicle','按预算与旅行方式选车，再核对座位、行李与具体版本。','Choose by budget and journey type, then confirm seats, luggage and exact trim.'],[uiIcon('check'),'确认用车安排','Confirm the arrangements','通过邮件确认实际报价、取还车点与服务方式，再安排出发。','Confirm the actual quote, pickup and return points, and service by email before departure.']].map((step,i)=>`<article><span class="rental-step-number">0${i+1}</span>${step[0]}<h3>${serviceCopy(step[1],step[2])}</h3><p>${serviceCopy(step[3],step[4])}</p></article>`).join('')}</div></section>`}
